set -e
cd "$(dirname "$0")"
mkdir -p site slow-site
cat > fetch-in-segments.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Fetches <url> as <n> byte ranges at once with one curl command, joins the segments in
# order into joined, and compares the result with <original>.
# Usage: sh fetch-in-segments.sh <url> <n> <original>
url=$1; n=$2; original=$3

# The size, from a HEAD request, and the segment length, rounded up.
size=$(curl -s -f -I -o /dev/null -w "%header{content-length}" "$url") || exit
seg=$(( (size + n - 1) / n ))

# One transfer per segment, separated by --next; the last segment stops at the last byte.
set --
i=0
while [ "$i" -lt "$n" ]; do
  first=$(( i * seg )); last=$(( first + seg - 1 ))
  [ "$last" -lt "$size" ] || last=$(( size - 1 ))
  [ "$i" -eq 0 ] || set -- "$@" --next
  set -- "$@" -s -f -r "$first-$last" -o "segment$i" -w "%{http_code} %header{content-range}\n" "$url"
  i=$(( i + 1 ))
done
curl --parallel --parallel-immediate "$@" > segments.txt || exit
sort -k3n segments.txt

# Join in segment order, not in the order the transfers ended, then compare byte for byte.
: > joined
i=0
while [ "$i" -lt "$n" ]; do cat "segment$i" >> joined; i=$(( i + 1 )); done
echo "joined: $(wc -c < joined | tr -d ' ') bytes"
if cmp -s joined "$original"; then echo "identical"; else echo "differs"; exit 1; fi
EOF
cat > seen-by-server.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Reads a surl -v log: the Range headers surl received, the 206 answers it gave, and how
# many connections (exchange numbers) carried them.
# Usage: sh seen-by-server.sh <log>
# surl writes its log a moment after curl is done: wait until every exchange it opened has ended, 10 s at most.
i=0; until [ "$(grep -c '\* Exchange [0-9]* opened' "$1")" = "$(grep -c '\* Exchange [0-9]* ended' "$1")" ]; do i=$((i+1)); [ $i -ge 100 ] && break; sleep 0.1; done
grep '< Range: ' "$1" | sed -e 's/^#[0-9]* < //' -e 's/\\r\\n$//' | sort -t '=' -k2n
echo "answered 206: $(grep -c '\* GET /big.bin: 206' "$1")"
echo "connections: $(grep '\* GET /big.bin: 206' "$1" | cut -d' ' -f1 | sort -u | wc -l | tr -d ' ')"
EOF
head -c 1000000 /dev/urandom > site/big.bin
cp site/big.bin slow-site/big.bin
surl -v --log-file surl.log --directory site http://127.0.0.1:8080/ &
sleep 1
sh fetch-in-segments.sh http://127.0.0.1:8080/big.bin 4 site/big.bin
kill $(jobs -p)
